package com.naslink.ui.components

/**
 * Pulls the small preview most cameras store inside a JPEG's EXIF block.
 *
 * Why this exists: a preview generated by downloading the whole file costs one full read
 * per picture, which is fine for a 3 MB phone photo and ruinous for a 30 MB one. Those
 * files still have a 160–320 px thumbnail sitting in the first few kilobytes, and reading
 * 256 KB instead of 30 MB turns a stall into a frame.
 *
 * Hand-written rather than `android.media.ExifInterface`: that class reads the **entire**
 * stream for formats other than JPEG (and reads to the end of the scan for some JPEGs),
 * which defeats the point of reading a bounded prefix. This only ever looks at the bytes
 * it was handed and gives up on anything it does not understand — the caller then falls
 * back to a full read or to the file-type icon.
 */
internal object JpegExifThumbnail {

    private const val MARKER_SOI = 0xD8
    private const val MARKER_EOI = 0xD9
    private const val MARKER_SOS = 0xDA
    private const val MARKER_APP1 = 0xE1

    private const val TIFF_TAG_JPEG_OFFSET = 0x0201
    private const val TIFF_TAG_JPEG_LENGTH = 0x0202
    private const val TIFF_ENTRY_BYTES = 12
    private const val MAX_TIFF_ENTRIES = 512
    private const val MAX_THUMBNAIL_BYTES = 4 * 1024 * 1024

    /**
     * @return the embedded preview as a standalone JPEG, or null when there is none
     *   (PNG, WebP, screenshots, stripped metadata, truncated input).
     */
    fun extract(bytes: ByteArray): ByteArray? {
        if (bytes.size < 4) return null
        if (u8(bytes, 0) != 0xFF || u8(bytes, 1) != MARKER_SOI) return null
        var position = 2
        while (position + 1 < bytes.size) {
            if (u8(bytes, position) != 0xFF) return null
            // Encoders may pad with 0xFF before the marker code.
            var markerAt = position
            while (markerAt + 1 < bytes.size && u8(bytes, markerAt + 1) == 0xFF) markerAt++
            if (markerAt + 1 >= bytes.size) return null
            val marker = u8(bytes, markerAt + 1)
            when {
                // Markers without a length field.
                marker == MARKER_SOI || marker == 0x01 || marker in 0xD0..0xD7 -> position = markerAt + 2
                // Past the metadata: the scan data starts here.
                marker == MARKER_SOS || marker == MARKER_EOI -> return null
                else -> {
                    if (markerAt + 3 >= bytes.size) return null
                    val length = (u8(bytes, markerAt + 2) shl 8) or u8(bytes, markerAt + 3)
                    if (length < 2) return null
                    val payload = markerAt + 4
                    val end = payload + length - 2
                    if (end > bytes.size) return null
                    if (marker == MARKER_APP1 && end - payload >= EXIF_HEADER_BYTES && isExifHeader(bytes, payload)) {
                        // A malformed block must not abandon the scan: later segments are
                        // still worth checking.
                        parseTiff(bytes, payload + EXIF_HEADER_BYTES, end)?.let { return it }
                    }
                    position = end
                }
            }
        }
        return null
    }

    private fun isExifHeader(bytes: ByteArray, at: Int): Boolean =
        bytes[at] == 'E'.code.toByte() &&
            bytes[at + 1] == 'x'.code.toByte() &&
            bytes[at + 2] == 'i'.code.toByte() &&
            bytes[at + 3] == 'f'.code.toByte() &&
            bytes[at + 4] == 0.toByte() &&
            bytes[at + 5] == 0.toByte()

    /**
     * Walks the TIFF header inside an APP1 payload.
     *
     * The preview lives in IFD1 (the second directory) in every spec-conforming writer,
     * but some produce it in IFD0, so both are inspected.
     */
    private fun parseTiff(bytes: ByteArray, base: Int, limit: Int): ByteArray? {
        if (limit - base < 8) return null
        val littleEndian = when {
            bytes[base] == 0x49.toByte() && bytes[base + 1] == 0x49.toByte() -> true
            bytes[base] == 0x4D.toByte() && bytes[base + 1] == 0x4D.toByte() -> false
            else -> return null
        }
        if (readU16(bytes, base + 2, littleEndian) != 42) return null
        var ifdOffset = readU32(bytes, base + 4, littleEndian)
        var visited = 0
        while (visited < 2 && ifdOffset > 0) {
            val ifd = base.toLong() + ifdOffset
            if (ifd + 2 > limit) return null
            val count = readU16(bytes, ifd.toInt(), littleEndian)
            if (count == 0 || count > MAX_TIFF_ENTRIES) return null
            val entriesEnd = ifd + 2 + count.toLong() * TIFF_ENTRY_BYTES
            if (entriesEnd + 4 > limit) return null
            var previewOffset = -1L
            var previewLength = -1L
            for (index in 0 until count) {
                val entry = (ifd + 2 + index.toLong() * TIFF_ENTRY_BYTES).toInt()
                when (readU16(bytes, entry, littleEndian)) {
                    TIFF_TAG_JPEG_OFFSET -> previewOffset = readU32(bytes, entry + 8, littleEndian)
                    TIFF_TAG_JPEG_LENGTH -> previewLength = readU32(bytes, entry + 8, littleEndian)
                }
            }
            readPreview(bytes, base, limit, previewOffset, previewLength)?.let { return it }
            ifdOffset = readU32(bytes, entriesEnd.toInt(), littleEndian)
            visited++
        }
        return null
    }

    private fun readPreview(
        bytes: ByteArray,
        base: Int,
        limit: Int,
        offset: Long,
        length: Long,
    ): ByteArray? {
        if (offset <= 0 || length <= 0) return null
        if (length > MAX_THUMBNAIL_BYTES) return null
        val start = base.toLong() + offset
        val end = start + length
        if (start < base || end > limit) return null
        val startIndex = start.toInt()
        val endIndex = end.toInt()
        if (endIndex - startIndex < 4) return null
        if (u8(bytes, startIndex) != 0xFF || u8(bytes, startIndex + 1) != MARKER_SOI) return null
        return bytes.copyOfRange(startIndex, endIndex)
    }

    private fun u8(bytes: ByteArray, at: Int): Int = bytes[at].toInt() and 0xFF

    private fun readU16(bytes: ByteArray, at: Int, littleEndian: Boolean): Int {
        val first = u8(bytes, at)
        val second = u8(bytes, at + 1)
        return if (littleEndian) first or (second shl 8) else (first shl 8) or second
    }

    private fun readU32(bytes: ByteArray, at: Int, littleEndian: Boolean): Long {
        val b0 = u8(bytes, at).toLong()
        val b1 = u8(bytes, at + 1).toLong()
        val b2 = u8(bytes, at + 2).toLong()
        val b3 = u8(bytes, at + 3).toLong()
        return if (littleEndian) {
            b0 or (b1 shl 8) or (b2 shl 16) or (b3 shl 24)
        } else {
            (b0 shl 24) or (b1 shl 16) or (b2 shl 8) or b3
        }
    }

    private const val EXIF_HEADER_BYTES = 6
}
